@pytest.mark.parametrize("petId,expected_status",[ 
    (10, 200),
    (-1, 400),
    (999999, 404),  # Non-existent pet
])
def test_get_pet_by_id_authenticated(api_client, valid_api_key, petId, expected_status):
    """
    Test GET /pet/{petId} with valid API key.
    """
    headers = {"Authorization": valid_api_key}
    endpoint = f"pet/{petId}"
    response = api_client.get(endpoint, headers=headers)
    assert response.status_code == expected_status

    if response.status_code == 200:
        pet_data = response.json()
        validate(instance=pet_data, schema=pet_response_schema)
    elif response.status_code == 400:
        assert "Invalid ID supplied" in response.text
    elif response.status_code == 404:
        assert "Pet not found" in response.text


